const options = ts.convertCompilerOptionsFromJson(ts.readConfigFile('tsconfig.json', ts.sys.readFile).config.compilerOptions, process.cwd()).options;
const program = ts.createProgram(ctx.files.filter(f=>f.endsWith('.ts')), options);
const checker = program.getTypeChecker();
const targetFile = program.getSourceFile(path.resolve('src/utilities/typeFromAST.ts'));
