      if (symbol===target) {
        const ownDeclaration = ts.isFunctionDeclaration(n.parent) && n.parent.name===n;
        const start = sf.getLineAndCharacterOfPosition(n.getStart(sf));
        const end = sf.getLineAndCharacterOfPosition(n.end);
        const row = {target:'typeFromAST',file:f,line:start.line+1,column:start.character,end_line:end.line+1,end_column:end.character};
        (ownDeclaration ? excluded : references).push(row);
